#!/usr/bin/env node
// Generates TypeScript and Go types from packages/protocol/schema/protocol.json.
// The schema is the single source of truth for the Gateway protocol (docs/SPEC.md §20).
//
// Usage: node codegen.mjs [--check] [--schema <file>] [--ts-out <file>] [--go-out <file>]
//   --check  don't write; exit 1 if the generated files differ from what's on disk (CI drift check)
import { existsSync, readFileSync, writeFileSync, mkdirSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { spawnSync } from "node:child_process";

const here = dirname(fileURLToPath(import.meta.url));
const root = resolve(here, "../../..");
const argv = process.argv.slice(2);
const arg = (name, fallback) => {
  const i = argv.indexOf(name);
  return i >= 0 && argv[i + 1] ? resolve(argv[i + 1]) : fallback;
};
const check = argv.includes("--check");
const schemaPath = arg("--schema", join(root, "packages/protocol/schema/protocol.json"));
const tsOut = arg("--ts-out", join(root, "packages/protocol/gen/ts/index.ts"));
const goOut = arg("--go-out", join(root, "apps/cli/internal/protocol/protocol_gen.go"));

const schema = JSON.parse(readFileSync(schemaPath, "utf8"));
const header = "Code generated by packages/protocol/scripts/codegen.mjs. DO NOT EDIT.";

// ---------- helpers ----------
const pascal = (s) => s.replace(/(^|[._-])(\w)/g, (_, __, c) => c.toUpperCase());
const goField = (s) => {
  const p = pascal(s);
  // Go initialisms
  return p.replace(/Id$/, "ID").replace(/Ms$/, "Ms").replace(/^Pid$/, "PID").replace(/^Http$/, "HTTP").replace(/^Url$/, "URL");
};

function tsType(t) {
  if (t.$ref) return t.$ref;
  if (t.enum) return t.enum.map((v) => JSON.stringify(v)).join(" | ");
  switch (t.type) {
    case "string": return "string";
    case "integer":
    case "number": return "number";
    case "boolean": return "boolean";
    case "array": return `${tsType(t.items)}[]`;
    case "object":
      if (!t.properties || Object.keys(t.properties).length === 0) return "Record<string, never>";
      return "{ " + Object.entries(t.properties).map(([k, v]) => `${k}${(t.required ?? []).includes(k) ? "" : "?"}: ${tsType(v)}`).join("; ") + " }";
    default: throw new Error(`unsupported type ${JSON.stringify(t)}`);
  }
}

function goType(t) {
  if (t.$ref) return t.$ref;
  if (t.enum) return "string";
  switch (t.type) {
    case "string": return "string";
    case "integer": return "int64";
    case "number": return "float64";
    case "boolean": return "bool";
    case "array": return `[]${goType(t.items)}`;
    case "object": return "map[string]any";
    default: throw new Error(`unsupported type ${JSON.stringify(t)}`);
  }
}

// ---------- TypeScript ----------
let ts = `// ${header}\n\nexport const PROTOCOL_VERSION = ${JSON.stringify(schema.protocolVersion)};\n\n`;
for (const [name, t] of Object.entries(schema.types)) {
  if (t.description) ts += `/** ${t.description} */\n`;
  if (t.type === "object") {
    const props = t.properties ?? {};
    const req = t.required ?? [];
    if (Object.keys(props).length === 0) {
      ts += `export type ${name} = Record<string, never>;\n\n`;
      continue;
    }
    ts += `export interface ${name} {\n`;
    for (const [k, v] of Object.entries(props)) {
      if (v.description) ts += `  /** ${v.description} */\n`;
      ts += `  ${k}${req.includes(k) ? "" : "?"}: ${tsType(v)};\n`;
    }
    ts += `}\n\n`;
  } else {
    ts += `export type ${name} = ${tsType(t)};\n\n`;
  }
}
ts += `export const ErrorCodes = {\n`;
for (const [name, e] of Object.entries(schema.errors)) ts += `  ${name}: ${e.code},\n`;
ts += `} as const;\nexport type ErrorName = keyof typeof ErrorCodes;\n\n`;
ts += `export const ErrorMessages: Record<ErrorName, string> = {\n`;
for (const [name, e] of Object.entries(schema.errors)) ts += `  ${name}: ${JSON.stringify(e.message)},\n`;
ts += `};\n\n`;
ts += `export interface Methods {\n`;
for (const [m, d] of Object.entries(schema.methods)) {
  if (d.description) ts += `  /** ${d.description} */\n`;
  ts += `  ${JSON.stringify(m)}: { params: ${d.params}; result: ${d.result} };\n`;
}
ts += `}\nexport type MethodName = keyof Methods;\n`;
ts += `export const METHOD_NAMES: MethodName[] = ${JSON.stringify(Object.keys(schema.methods))};\n\n`;
// Runtime type metadata: the Gateway validates params and ctx against it (apps/browser/src/gateway/validate.ts).
const stripDocs = (v) => JSON.parse(JSON.stringify(v, (k, x) => (k === "description" ? undefined : x)));
ts += `/** A type from the schema, for runtime validation. */
export interface TypeSchema {
  type?: "string" | "integer" | "number" | "boolean" | "array" | "object";
  $ref?: string;
  enum?: string[];
  items?: TypeSchema;
  properties?: Record<string, TypeSchema>;
  required?: string[];
  minimum?: number;
  maximum?: number;
  minLength?: number;
  maxLength?: number;
}

export const TYPE_SCHEMAS: Record<string, TypeSchema> = ${JSON.stringify(stripDocs(schema.types), null, 2)};

/** Params type of each method. */
export const METHOD_PARAMS: Record<MethodName, string> = ${JSON.stringify(Object.fromEntries(Object.entries(schema.methods).map(([m, d]) => [m, d.params])), null, 2)};

`;
ts += `export interface RpcRequest<M extends MethodName = MethodName> {\n  jsonrpc: "2.0";\n  id: number | string;\n  method: M;\n  params?: Methods[M]["params"];\n  ctx?: AgentContext;\n}\n\n`;
ts += `export interface RpcError {\n  code: number;\n  message: string;\n  data?: { name: ErrorName; hint?: string };\n}\n\n`;
ts += `export interface RpcResponse<M extends MethodName = MethodName> {\n  jsonrpc: "2.0";\n  id: number | string | null;\n  result?: Methods[M]["result"];\n  error?: RpcError;\n}\n`;

// ---------- Go ----------
let go = `// ${header}\n\npackage protocol\n\n`;
go += `// ProtocolVersion is the Gateway protocol version this client speaks.\nconst ProtocolVersion = ${JSON.stringify(schema.protocolVersion)}\n\n`;
for (const [name, t] of Object.entries(schema.types)) {
  if (t.type !== "object") continue;
  if (t.description) go += `// ${name}: ${t.description}\n`;
  go += `type ${name} struct {\n`;
  const req = t.required ?? [];
  for (const [k, v] of Object.entries(t.properties ?? {})) {
    const omit = req.includes(k) ? "" : ",omitempty";
    const comment = v.description ? ` // ${v.description}` : "";
    // Optional nested objects are pointers, so "absent" (nil) differs from "empty".
    const type = v.$ref && !req.includes(k) ? `*${goType(v)}` : goType(v);
    go += `\t${goField(k)} ${type} \`json:"${k}${omit}"\`${comment}\n`;
  }
  go += `}\n\n`;
}
go += `// Method names.\nconst (\n`;
for (const m of Object.keys(schema.methods)) go += `\tMethod${pascal(m)} = ${JSON.stringify(m)}\n`;
go += `)\n\n// Error codes.\nconst (\n`;
for (const [name, e] of Object.entries(schema.errors)) go += `\t${pascal(name.toLowerCase())} = ${e.code} // ${name}\n`;
go += `)\n\n// ErrorNames maps error codes to their names.\nvar ErrorNames = map[int]string{\n`;
for (const [name, e] of Object.entries(schema.errors)) go += `\t${e.code}: ${JSON.stringify(name)},\n`;
go += `}\n`;

go = gofmt(go);

// Everything is generated before anything is written, so a schema error never leaves partial output.
const rel = (p) => p.replace(root + "\\", "").replace(root + "/", "");
const outputs = [
  [tsOut, ts],
  [goOut, go],
];

if (check) {
  const stale = outputs.filter(([file, content]) => !existsSync(file) || readFileSync(file, "utf8") !== content);
  for (const [file] of stale) console.error(`codegen: ${rel(file)} is out of date; run \`npm run codegen\``);
  if (stale.length) process.exit(1);
  console.log("codegen: generated files are up to date");
} else {
  for (const [file, content] of outputs) {
    mkdirSync(dirname(file), { recursive: true });
    writeFileSync(file, content);
    console.log(`codegen: wrote ${rel(file)}`);
  }
}

/** Formats Go source with gofmt when it's available, so output matches what `go fmt` would produce. */
function gofmt(src) {
  const candidates = ["gofmt", join(process.env.ProgramFiles ?? "C:\\Program Files", "Go", "bin", "gofmt.exe"), "/usr/local/go/bin/gofmt"];
  for (const bin of candidates) {
    const r = spawnSync(bin, [], { input: src, encoding: "utf8" });
    if (r.status === 0) return r.stdout;
    if (r.error?.code !== "ENOENT" && r.status !== null) throw new Error(`gofmt failed:\n${r.stderr}`);
  }
  console.warn("codegen: gofmt not found; Go output is unformatted");
  return src;
}
